/**
 * Binary content as a runtime-neutral byte stream. Node implementations convert with
 * `Readable.from` / `Readable.toWeb` as needed.
 * @public
 */
export type FileContent = AsyncIterable<Uint8Array>;

/**
 * One stored file. Visible to middleware (read-only) and to the metadata adapter.
 * @public
 */
export interface FileRecord {
  /** Generated by the Service; written into Unit snapshots, so it is permanent and never reused. */
  readonly fileID: string;
  /** Original file name from the multipart `filename` or the server-side writer. */
  readonly name: string;
  /** Bytes actually written (after inflate). The upload `size` query is only a hint. */
  readonly size: number;
  /** MIME type used for the proxy download response and the object store `ContentType`. */
  readonly contentType: string;
  /** Protocol `FileSource` value. Unknown values are stored as-is. */
  readonly source: number;
  /** Owner object: userID for HttpImport/HttpExport, unitID for UnitEmbedded. */
  readonly assign: string;
  /** Opaque locator returned by the blob store. Never returned to clients. */
  readonly blobKey: string;
  /** Milliseconds since the Unix epoch; drives expiry. */
  readonly createdAt: number;
}

// ---- HTTP layer (built-in ownership check and middleware) ----

/** @public */
export interface UploadInput {
  readonly name: string;
  readonly contentType: string;
  /** Client-declared size hint; not validated and not stored. */
  readonly size?: number;
  readonly source: number;
  readonly assign: string;
  readonly flate: boolean;
  readonly content: FileContent;
}

/**
 * The read-only view of an upload that middleware sees before any bytes are read.
 * @public
 */
export interface UploadRequest {
  readonly name: string;
  readonly contentType: string;
  readonly size?: number;
  readonly source: number;
  readonly assign: string;
  readonly flate: boolean;
}

/** @public */
export interface SignUrlInput {
  readonly fileID: string;
}
/** @public */
export interface SignUrlRequest extends SignUrlInput {}

/** @public */
export interface DownloadInput {
  readonly fileID: string;
}
/** @public */
export interface DownloadRequest extends DownloadInput {}

// ---- Trusted layer (for trusted server code such as Exchange and the application; no checks, no middleware) ----

/** @public */
export interface CreateFileInput {
  readonly name: string;
  readonly contentType: string;
  readonly source: number;
  readonly assign: string;
  readonly content: FileContent;
}
/** @public */
export interface CreateFileRequest {
  readonly name: string;
  readonly contentType: string;
  readonly source: number;
  readonly assign: string;
}

/** @public */
export interface GetFileRequest {
  readonly fileID: string;
}
/** @public */
export interface OpenFileRequest {
  readonly fileID: string;
}
/** @public */
export interface DeleteFileRequest {
  readonly fileID: string;
}

/**
 * Ordering is fixed to `(createdAt, fileID)` ascending. `cursor` is opaque: pass back the
 * `nextCursor` of the previous page to continue.
 * @public
 */
export interface ListFilesInput {
  readonly source: number;
  readonly assign?: string;
  /** Exclusive upper bound on `createdAt`, in milliseconds. */
  readonly createdBefore?: number;
  readonly limit: number;
  readonly cursor?: string;
}
/** @public */
export interface ListFilesRequest extends ListFilesInput {}

/**
 * `nextCursor` is `null` when there are no more records; a short page is not an end marker.
 * @public
 */
export interface ListFilesResult {
  readonly records: readonly FileRecord[];
  readonly nextCursor: string | null;
}

/**
 * Per-run overrides for `cleanupExpiredFiles`; defaults follow the Service options.
 * @public
 */
export interface CleanupInput {
  readonly retentionMs?: number;
  readonly batchSize?: number;
  readonly maxPerRun?: number;
  readonly batchGapMs?: number;
}
/**
 * The request every adapter call made during one cleanup run carries, so adapters can tell
 * system cleanup from user deletes.
 * @public
 */
export interface CleanupRequest {
  readonly sources: readonly number[];
  readonly createdBefore: number;
  readonly batchSize: number;
  readonly maxPerRun: number;
  readonly batchGapMs: number;
}

/** @public */
export type FileRequest =
  | UploadRequest
  | SignUrlRequest
  | DownloadRequest
  | CreateFileRequest
  | GetFileRequest
  | OpenFileRequest
  | DeleteFileRequest
  | ListFilesRequest
  | CleanupRequest;

// ---- Results ----

/** @public */
export interface DirectUrl {
  readonly url: string;
  /** Milliseconds since the Unix epoch. */
  readonly expiresAt: number;
}

/**
 * `direct` is present only when the blob store signed a direct link.
 * @public
 */
export interface SignUrlResult {
  readonly record: FileRecord;
  readonly direct?: DirectUrl;
}

/** @public */
export interface OpenDownloadResult {
  readonly record: FileRecord;
  readonly content: FileContent;
}

/** @public */
export interface OpenFileResult {
  readonly record: FileRecord;
  readonly content: FileContent;
}

/** @public */
export interface CleanupResult {
  readonly scanned: number;
  readonly deleted: number;
  readonly failed: number;
}
